#include <malloc.h>

#define OK   1
#define ERROR  0
#define TRUE 1
#define FALSE 0

typedef char ElemType;
typedef struct Node    /*结点类型定义*/ 
{ 
	ElemType data;
	struct Node  * next;
}Node, *LinkList;  /* LinkList为结构指针类型*/

/* 示例：用上面的结点类型手工搭一条头插法链表，再顺着 next 打印。 */
int main(void)
{
    Node *head = NULL;
    Node *node;
    char letters[] = "abc";
    int i;

    for (i = 0; i < 3; i++)
    {
        node = (Node *)malloc(sizeof(Node));
        node->data = letters[i];
        node->next = head;
        head = node;
    }

    printf("头插法建表后的顺序: ");
    for (node = head; node != NULL; node = node->next)
        printf("%c ", node->data);
    printf("\n");

    for (node = head; node != NULL; )
    {
        Node *next = node->next;
        free(node);
        node = next;
    }
    return 0;
}

