/* ===== 以下来自 ch02-staticlist ===== */
#include<stdio.h>
#include<stdlib.h>

#define  Maxsize 100
#define  ElemType char

typedef  struct
{	
	ElemType data;
	int cursor;
}Component, StaticList[Maxsize];

/* 示例：静态链表靠 cursor 串起来，跟着 cursor 走就是遍历。 */
int main(void)
{
    StaticList L;
    int i;

    for (i = 0; i < Maxsize; i++)
    {
        L[i].data = (char)('A' + i);
        L[i].cursor = -1;
    }
    L[0].cursor = 1;                   /* A -> B -> C -> D */
    L[1].cursor = 2;
    L[2].cursor = 3;

    printf("静态链表: ");
    for (i = 0; i != -1; i = L[i].cursor)
        printf("%c ", L[i].data);
    printf("\n");
    printf("第 3 个结点的后继下标: %d\n", L[2].cursor);
    return 0;
}

