/* ===== 以下来自 ch02-dlinklist ===== */
#include <stdio.h>
#include <stdlib.h>
#include <malloc.h>

#define OK   1
#define ERROR  0
#define TRUE 1
#define FALSE 0

typedef char ElemType;

typedef struct DNode
{
	ElemType data;
	struct DNode *prior, *next;
}DNode,	*DoubleList;

void CreateList(DoubleList L)
/*通过键盘输入表中元素值，利用尾插法建单链表,并返回该单链表头指针L*/
{ 
	DNode *r, *s;
	char c;
	int   flag =1; /*设置一个标志，初值为1，当输入"$"时，flag为0，建表结束*/
	L->next=L;
	L->prior=L;
	r=L;              
	while(flag)         
	{
		c=getchar();
		if(c!='$')
		{
			s=(DNode*)malloc(sizeof(DNode));
			s->data=c;
			r->next=s;
			s->prior=r;
			r=s;
		}
		else
		{
			flag=0;
			r->next=L;   
			L->prior=r;
		}
	}   /*while*/
} 

/* 示例：建表函数读字符串（$ 结束），prior 和 next 都要接上，
   所以既能顺着 next 正着走，也能顺着 prior 倒着走。 */
int main(void)
{
    DNode head;
    DNode *p;

    CreateList(&head);

    printf("正向 (next): ");
    for (p = head.next; p != &head; p = p->next)
        printf("%c ", p->data);
    printf("\n反向 (prior): ");
    for (p = head.prior; p != &head; p = p->prior)
        printf("%c ", p->data);
    printf("\n");
    return 0;
}

