#include <stdio.h>
#include <stdlib.h>
#include <malloc.h>

#define OK   1
#define ERROR  0
#define TRUE 1
#define FALSE 0

typedef struct Polynode 
{
	int coef;
	int exp;
	struct Polynode *next;
}Polynode, *Polylist;

/* 示例：手工串出 3x^2 + 5x + 7 三个结点，看看多项式在内存里长什么样。 */
int main(void)
{
    Polynode *a = (Polynode *)malloc(sizeof(Polynode));
    Polynode *b = (Polynode *)malloc(sizeof(Polynode));
    Polynode *c = (Polynode *)malloc(sizeof(Polynode));
    Polynode *p;

    a->coef = 3; a->exp = 2; a->next = b;
    b->coef = 5; b->exp = 1; b->next = c;
    c->coef = 7; c->exp = 0; c->next = NULL;

    printf("多项式: ");
    for (p = a; p != NULL; p = p->next)
    {
        printf("%d", p->coef);
        if (p->exp > 0)
            printf("x^%d", p->exp);
        if (p->next != NULL)
            printf(" + ");
    }
    printf("\n");
    return 0;
}

