{		
	if(ch=='(' && str==')')
	{
		return TRUE;
	}
	else if(ch=='[' && str==']')
	{
		return TRUE;
	}
	else if(ch=='{' && str=='}')
	{
		return TRUE;
	}
	else 
		return FALSE;
}

int main(void) {
  SeqStack S;
  int accepted = 0, rejected = 0, i;

  InitStack(&S);
  for (i = 0; i < Stack_Size + 5; i++) {
    if (Push(&S, (char)('A' + i % 26)) == TRUE) {
      accepted++;
    } else {
      rejected++;
    }
  }

  printf("尝试入栈 %d 次\n", Stack_Size + 5);
