   ============================================================ */
#define TRUE 1
#define FALSE 0
#define M 100

typedef struct
{
	StackElementType Stack[M];
	StackElementType top[2];  /*top[0]和top[1]分别为两个栈顶指示器*/
}DqStack;

/*初始化操作。*/
void InitStack(DqStack *S)
{
	S->top[0]=-1;
	S->top[1]=M;
}

/*进栈操作。*/
int Push(DqStack *S,StackElementType x,int i)
{
	/*把数据元素x压入i号堆栈*/
	if(S->top[0]+1==S->top[1]) /*栈已满*/
		return(FALSE);
	switch(i)
	{
	case 0:
		S->top[0]++;
		S->Stack[S->top[0]]=x;
		break;
	case 1:
		S->top[1]--;
		S->Stack[S->top[1]]=x;
		break;
	default:  /*参数错误*/
        return(FALSE);  /* 原书此处漏了分号，为能编译已补 */
 	}
	return(TRUE);
}

/*出栈操作。*/
int Pop(DqStack *S,StackElementType *x,int i)
{
	/* 从i 号堆栈中弹出栈顶元素并送到x中 */
	switch(i)
	{
	case 0:
		if(S->top[0]==-1)  
			return(FALSE);
		*x=S->Stack[S->top[0]];
		S->top[0]--;
		break;
	case 1:
		if(S->top[1]==M)  
			return(FALSE);
		*x=S->Stack[S->top[1]];
		S->top[1]++;
		break;
	default:
		return(FALSE);
	}
	return(TRUE);
}


int main(void) {
  DqStack S;
  StackElementType x;
  int i;

  InitStack(&S);
  for (i = 1; i <= 3; i++) Push(&S, i * 100, 0);
  for (i = 1; i <= 2; i++) Push(&S, i * 7, 1);

  printf("0 号栈 top[0] = %d，1 号栈 top[1] = %d\n", S.top[0], S.top[1]);
  printf("两栈之间还剩 %d 个空位\n", S.top[1] - S.top[0] - 1);

  printf("0 号栈出栈: ");
  while (Pop(&S, &x, 0) == TRUE) printf("%d ", x);
  printf("\n1 号栈出栈: ");
  while (Pop(&S, &x, 1) == TRUE) printf("%d ", x);
  putchar('\n');
  return 0;
}

