}

/* 示例把上面的基本运算串起来跑一遍：入栈、取栈顶、出栈，再看判空判满。 */
int main(void)
{
    SeqStack S;
    char word[] = "abcde";
    char x;
    int i;

    InitStack(&S);
    for (i = 0; word[i] != '\0'; i++)
        Push(&S, word[i]);

    printf("入栈后元素个数: %d\n", S.top + 1);
    GetTop(&S, &x);
    printf("栈顶元素: %c\n", x);
    printf("出栈顺序: ");
    while (!IsEmpty(&S))
    {
        Pop(&S, &x);
        printf("%c ", x);
    }
    printf("\n空栈再出栈: %d\n", Pop(&S, &x));
    printf("判满: %d\n", IsFull(&S));
    return 0;
}

#include <stdio.h>
