#define StackElementType char

/* ===== 以下来自 ch03-linkstack ===== */
#define TRUE 1
#define FALSE 0

typedef struct node
{
	StackElementType data;
	struct node *next;
}LinkStackNode;

typedef LinkStackNode *LinkStack;

/*进栈操作。*/
int Push(LinkStack top, StackElementType x)/* 将数据元素x压入栈top中 */ 
{
	LinkStackNode *temp;
	temp=(LinkStackNode *)malloc(sizeof(LinkStackNode));
 	if(temp==NULL)  
 		return(FALSE);   /* 申请空间失败 */
	temp->data=x;
	temp->next=top->next;
	top->next=temp;   /* 修改当前栈顶指针 */ 
	return(TRUE);
}

/*出栈操作。*/
int Pop(LinkStack top, StackElementType *x)
{  
	/* 将栈top的栈顶元素弹出，放到x所指的存储空间中 */
	LinkStackNode * temp;
	temp=top->next;
	if(temp==NULL)  /*栈为空*/
		return(FALSE);
	top->next=temp->next;
	*x=temp->data;
	free(temp);   /* 释放存储空间 */
	return(TRUE);
}

/* 示例：链栈就是没有头结点数据的单链表，Push 插在表头、Pop 摘表头。 */
int main(void)
{
    LinkStack top = (LinkStack)malloc(sizeof(LinkStackNode));
    char word[] = "xyz";
    char x;
    int i;

    top->next = NULL;
    for (i = 0; word[i] != '\0'; i++)
        Push(top, word[i]);

    printf("链栈出栈顺序: ");
    while (top->next != NULL)
    {
        Pop(top, &x);
        printf("%c ", x);
    }
    printf("\n空栈再出栈: %d\n", Pop(top, &x));
    free(top);
    return 0;
}

