{
    SeqQueue Q;
    int i;
    int x;

    InitQueue(&Q);
    printf("空队判空: %d\n", IsEmpty(&Q));
    for (i = 1; i <= 4; i++)
        EnterQueue(&Q, i * 10);

    GetHead(&Q, &x);
    printf("队头元素: %d\n", x);
    printf("出队顺序: ");
    while (DeleteQueue(&Q, &x))
        printf("%d ", x);
    printf("\n");
    return 0;
}

