    {
        node = (Block *)malloc(sizeof(Block));
        node->ch = source[i];
        node->next = NULL;
        if (s.head == NULL)
            s.head = node;
        else
            s.tail->next = node;
        s.tail = node;
        s.len++;
    }

    printf("串内容: ");
    for (node = s.head; node != NULL; node = node->next)
        printf("%c", node->ch);
    printf("\n串长度: %d\n", s.len);
    return 0;
}

