#define MAXSIZE 100
#define ElementType int

typedef struct
{
    int row,col;
    ElementType e;
} Triple;

typedef struct
{
    Triple data[MAXSIZE+1];
    int m,n,len;
} TSMatrix;

/* ===== 以下来自 ch05-5.3 ===== */
/*"按位快速转置"法*/

void FastTransposeTSMatrix(TSMatrix A,TSMatrix *B)
{ 
	/*基于矩阵的三元组表示，采用"按位快速转置"法，将矩阵A转置为矩阵B*/
	int col,t,p,q;
	int num[MAXSIZE], position[MAXSIZE];
	B->len=A.len; 
	B->n=A.m; 
	B->m=A.n;
	if(B->len)
	{
		for(col=1;col<=A.n;col++)
			num[col]=0;  
		for(t=1;t<=A.len;t++)
			num[A.data[t].col]++; /*计算每一列的非零元素的个数*/	
		position[1]=1;
		for(col=2;col<=A.n;col++)  /*求col列中第一个非零元素在B.data[ ]中的正确位置*/
			position[col]=position[col-1]+num[col-1]; 
		for(p=1;p<=A.len;p++)/*将被转置矩阵的三元组表A从头至尾扫描一次，实现矩阵转置*/
		{  
			col=A.data[p].col;  
			q=position[col];
			B->data[q].row=A.data[p].col;
			B->data[q].col=A.data[p].row;
			B->data[q].e=A.data[p].e;
			position[col]++;/* position[col]加1，指向下一个列号为col的非零元素在三元组表B中的下标值*/
		}/*end of for*/
	}
}

int main(void)
{
    TSMatrix A, B;
    int i;

    A.m = 3; A.n = 3; A.len = 3;
    A.data[1].row = 1; A.data[1].col = 1; A.data[1].e = 5;
    A.data[2].row = 2; A.data[2].col = 3; A.data[2].e = 7;
    A.data[3].row = 3; A.data[3].col = 2; A.data[3].e = 9;

    FastTransposeTSMatrix(A, &B);

    printf("转置后 %d 行 %d 列，%d 个非零元素:\n", B.m, B.n, B.len);
    for (i = 1; i <= B.len; i++)
        printf("  (%d,%d)=%d\n", B.data[i].row, B.data[i].col, B.data[i].e);
    return 0;
}

