/* ===== 以下来自 ch05-5.4 ===== */
/*建立稀疏矩阵的十字链表的算法*/


void CreateCrossList(CrossList *M)
{
	int m,n,t;
	OLNode *p,*q;
	int i,j,e;
	/*采用十字链表存储结构，创建稀疏矩阵M*/
	printf("输入M的行数,列数和非零元素的个数\n");
	scanf("%d,%d,%d",&m,&n,&t);  /*输入M的行数,列数和非零元素的个数*/
	M->m=m;
	M->n=n;
	M->len=t;
	if(!(M->row_head=(OLink *)malloc((m+1)*sizeof(OLink)))) 
		printf("error");
	if(!(M->col_head=(OLink *)malloc((n+1)*sizeof(OLink)))) 
		printf("error");
	for(i=0;i<=m;i++) M->row_head[i]=NULL;   /*各行链表为空*/
	for(j=0;j<=n;j++) M->col_head[j]=NULL;   /*各列链表为空*/   /*初始化行、列头指针向量，各行、列链表为空的链表*/

	printf("输入\n");
	for(scanf("%d,%d,%d",&i,&j,&e);i!=0;scanf("%d,%d,%d",&i,&j,&e))
	{
		if(!(p=(OLNode *)malloc(sizeof(OLNode)))) 
			printf("error");
		p->row=i;
		p->col=j;
		p->value=e;
		p->right=NULL; p->down=NULL;   /*示例补上：原段没有初始化这两个链域*/
		if(M->row_head[i]==NULL)   
			M->row_head[i]=p;
		else
		{  
			/*寻找行表中的插入位置*/
			for(q=M->row_head[i];q->right&&q->right->col<j;q=q->right);  /*空循环体*/
			p->right=q->right; 
			q->right=p;  /*完成插入*/
		}
		if(M->col_head[j]==NULL)   
			M->col_head[j]=p;
		else
		{  
			/*寻找列表中的插入位置*/
			for(q=M->col_head[j];q->down&&q->down->row<i;q=q->down);  /*空循环体*/
			p->down=q->down; 
			q->down=p;   /*完成插入*/
		}
	}
}

void main()
{
	CrossList M;

	CreateCrossList(&M);
	PrintCrossList(&M);
}

