	GraphKind kind;              /*图的种类*/
}OrthList;      /*图的十字链表表示法(Orthogonal List)*/

/* 原段调用的 LocateVertex 在书里由另一个文件给出，示例在这里补出实现。 */
int LocateVertex(OrthList *G, VertexData v)
{
    int j = Error, k;
    for (k = 0; k < G->vexnum; k++)
        if (G->vertex[k].data == v)
        {
            j = k;
            break;
        }
    return j;
}

/*建立一个有向图的十字链表的算法如下：*/



void  CrtOrthList(OrthList *g)
/*从终端输入n个顶点的信息和e条弧的信息，以建立一个有向图的十字链表*/
{
	int n,e;
	int i,j,k;
	char vt,vh;

	ArcNode *p;
	printf("从键盘输入图的顶点个数和弧的个数");
	fflush(stdin);
	scanf("%d,%d",&n,&e);  /*从键盘输入图的顶点个数和弧的个数*/
	g->vexnum = n;
	g->arcnum = e;
	for(i=0;i<n;i++) 
	{
		printf("输入图的顶点");
		fflush(stdin);
		scanf("%c",&g->vertex[i].data);
		g->vertex[i].firstin=NULL;g->vertex[i].firstout=NULL;
	}
	for(k=0;k<e;k++) 
	{
		printf("输入一条弧的两个顶点");
		fflush(stdin);
		scanf("%c,%c",&vt,&vh);
		i=LocateVertex(g,vt);
		j = LocateVertex(g,vh);
		p=(ArcNode*)malloc(sizeof(ArcNode));
		p->tailvex=i;
		p->headvex=j;
		p->tlink=g->vertex[i].firstout;
		g->vertex[i].firstout=p;
		p->hlink=g->vertex[j].firstin;
		g->vertex[j].firstin=p;
    }
}/* CrtOrthList */

