#include <stdio.h>
#include <stdlib.h>

/* v1..v6 就是 A..F；活动：A->B(3) A->C(2) B->D(2) B->E(3) C->D(4) C->F(3) D->F(2) E->F(1) */
#define MAX_VERTEX_NUM 10
#define TRUE 1
#define FALSE 0
#define Error -1
#define Ok 1

typedef char VertexData;

typedef struct ArcNode
{
    int adjvex;
    int weight;                       /* 活动持续时间 */
    struct ArcNode *nextarc;
} ArcNode;

typedef struct
{
    VertexData data;
    ArcNode *firstarc;
} VertexNode;

typedef struct
{
    VertexNode vertex[MAX_VERTEX_NUM];
    int vexnum, arcnum;
} AdjList;

int ve[MAX_VERTEX_NUM];               /* 每个顶点的最早发生时间 */

void AddArc(AdjList *g, int i, int j, int weight)   /* 头插，邻接表里同一顶点的出弧顺序会反过来 */
{
    ArcNode *p = (ArcNode *)malloc(sizeof(ArcNode));
    p->adjvex = j;
    p->weight = weight;
    p->nextarc = g->vertex[i].firstarc;
    g->vertex[i].firstarc = p;
}

/* 求各顶点的入度 */
void FindID(AdjList G, int indegree[MAX_VERTEX_NUM])
{
    int i;
    ArcNode *p;

    for (i = 0; i < G.vexnum; i++)
        indegree[i] = 0;
    for (i = 0; i < G.vexnum; i++)
    {
        p = G.vertex[i].firstarc;
        while (p != NULL)
        {
            indegree[p->adjvex]++;
            p = p->nextarc;
        }
    }
}

/* 拓扑排序：顺带把各顶点的最早发生时间算出来 */
int TopoOrder(AdjList G, int topological[])
{
    int indegree[MAX_VERTEX_NUM];
    int stack[MAX_VERTEX_NUM];
    int top = -1, count = 0, i, j, k;
    ArcNode *p;

    FindID(G, indegree);
    for (i = 0; i < G.vexnum; i++)
    {
        ve[i] = 0;
        if (indegree[i] == 0)
            stack[++top] = i;
    }

    while (top >= 0)
    {
        j = stack[top--];
        topological[count++] = j;
        p = G.vertex[j].firstarc;
        while (p != NULL)
        {
            k = p->adjvex;
            if (--indegree[k] == 0)
                stack[++top] = k;
            if (ve[j] + p->weight > ve[k])
                ve[k] = ve[j] + p->weight;
            p = p->nextarc;
        }
    }
    return count < G.vexnum ? Error : Ok;
}

void CriticalPath(AdjList G)
{
    int topological[MAX_VERTEX_NUM];
    int vl[MAX_VERTEX_NUM];
    int i, j, k, dut, ei, li;
    ArcNode *p;

    if (TopoOrder(G, topological) != Ok)
    {
        printf("这个有向图里有回路，没有关键路径\n");
        return;
    }

    for (i = 0; i < G.vexnum; i++)
        vl[i] = ve[G.vexnum - 1];       /* 汇点的最迟发生时间就是它的最早发生时间 */
    for (i = G.vexnum - 1; i >= 0; i--) /* 按逆拓扑顺序求各顶点的 vl */
    {
        j = topological[i];
        p = G.vertex[j].firstarc;
        while (p != NULL)
        {
            k = p->adjvex;
            dut = p->weight;
            if (vl[k] - dut < vl[j])
