	struct Mbtnode  *parent;
	int  keynum;
	KeyType  key[m+1];
	struct Mbtnode  *ptr[m+1];
} Mbtnode, *Mbtree;

int main(void)
{
    Mbtnode root;
    int i;

    root.parent = NULL;
    root.keynum = 2;
    for (i = 0; i <= m; i++)
    {
        root.key[i] = 0;
        root.ptr[i] = NULL;
    }
    root.key[1] = 10;
    root.key[2] = 20;

    printf("%d 阶 B 树，根里有 %d 个关键字\n", m, root.keynum);
    printf("关键字: ");
    for (i = 1; i <= root.keynum; i++)
        printf("%d ", root.key[i]);
    printf("\n还是叶子（ptr 全空）: %d\n", root.ptr[0] == NULL && root.ptr[1] == NULL);
    return 0;
}

