/* ===== 以下来自 ch08-hash ===== */
#include <stdio.h>
#include <stdlib.h>

#define  m   13
#define  NULLKEY  0
typedef  int  KeyType;    /* 假设关键字为整型 */
typedef  struct
{
	KeyType  key;
}RecordType;

typedef  RecordType  HashTable[m];

int main(void)
{
    HashTable ht;
    int keys[] = {18, 31, 5, 44};
    int i;

    for (i = 0; i < m; i++)
        ht[i].key = NULLKEY;
    for (i = 0; i < 4; i++)
        ht[keys[i] % m].key = keys[i];

    printf("表长 %d，NULLKEY 表示空\n", m);
    for (i = 0; i < m; i++)
        printf("  [%2d] %s\n", i, ht[i].key == NULLKEY ? "空" : "有值");
    printf("18 %% %d = %d，44 %% %d = %d：两个关键字落在同一个格子里，后写的把先写的挤掉了\n",
           m, 18 % m, m, 44 % m);
    return 0;
}

