/* ===== 以下来自 ch08-seq ===== */
#include <stdio.h>
#include <stdlib.h>

#define LIST_SIZE 20 

typedef char KeyType;
typedef int OtherType;

typedef struct
{
	KeyType key;
	OtherType other_data;
}RecordType;

typedef struct
{
	RecordType  r[LIST_SIZE+1];  /* r[0]为工作单元 */
	int length;
}RecordList;

int main(void)
{
    RecordList L;
    char keys[] = "ceadg";
    char wanted = 'a';
    int i;
    int found = 0;

    L.length = 5;
    for (i = 1; i <= L.length; i++)
    {
        L.r[i].key = keys[i - 1];
        L.r[i].other_data = i;
    }

    printf("表里的关键字: ");
    for (i = 1; i <= L.length; i++)
        printf("%c ", L.r[i].key);
    printf("\n");

    for (i = 1; i <= L.length; i++)
        if (L.r[i].key == wanted)
        {
            found = i;
            break;
        }
    printf("查找 '%c' 的比较次数: %d\n", wanted, found);
    return 0;
}

