/* ===== 以下来自 ch08-bst ===== */
#include <stdio.h>
#include <stdlib.h>

#define ENDKEY 0

typedef int KeyType;

typedef struct  node
{
	KeyType  key ; /*关键字的值*/
	struct node  *lchild,*rchild;/*左右指针*/
}BSTNode, *BSTree;

void show(BSTree t)
{
    if (t == NULL)
        return;
    show(t->lchild);
    printf("%d ", t->key);
    show(t->rchild);
}

int main(void)
{
    BSTNode n1, n2, n3;

    n1.key = 20; n1.lchild = &n2; n1.rchild = &n3;
    n2.key = 10; n2.lchild = NULL; n2.rchild = NULL;
    n3.key = 30; n3.lchild = NULL; n3.rchild = NULL;

    printf("中序遍历（就是排好序的顺序）: ");
    show(&n1);
    printf("\n根的关键字: %d\n", n1.key);
    return 0;
}

