/* ===== 以下来自 ch09-radixsort ===== */
#include <stdio.h>
#include <stdlib.h>

#define RADIX 10
#define KEY_SIZE 6
#define LIST_SIZE 20

typedef int KeyType;
typedef int OtherType;

typedef struct 
{
	KeyType key[KEY_SIZE];      /* 子关键字数组 */ 
	OtherType other_data;        /* 其它数据项 */ 

	int  next;                   /* 静态链域 */ 
} RecordType1;

typedef struct 
{
	RecordType1  r[LIST_SIZE+1];  /* r[0]为头结点 */
	int length;
	int keynum;
}SLinkList;                  /* 静态链表 */

typedef int PVector[RADIX];

int main(void)
{
    SLinkList L;
    int i;

    L.length = 2;
    L.keynum = 3;
    for (i = 0; i <= LIST_SIZE; i++)
    {
        L.r[i].next = 0;
        L.r[i].other_data = 0;
    }

    L.r[1].other_data = 1;
    L.r[1].key[1] = 4; L.r[1].key[2] = 9; L.r[1].key[3] = 7;
    L.r[1].next = 2;               /* 1 号记录后面跟着 2 号 */

    L.r[2].other_data = 2;
    L.r[2].key[1] = 2; L.r[2].key[2] = 0; L.r[2].key[3] = 5;
    L.r[2].next = 0;

    printf("记录数 %d, 子关键字个数 %d, 基数 %d\n", L.length, L.keynum, RADIX);
    printf("1 号记录的子关键字: %d %d %d\n", L.r[1].key[1], L.r[1].key[2], L.r[1].key[3]);
    printf("静态链: 1 号 -> %d 号\n", L.r[1].next);
    return 0;
}

